<?php
require __DIR__.'/core.php';require __DIR__.'/profile-core.php';require __DIR__.'/customers-core.php';
$_SERVER['SCRIPT_NAME']=preg_replace('~/account/enquiries.php$~','/account/index.php',$_SERVER['SCRIPT_NAME']);
$error='';$notice='';$b=null;$rows=[];$detail=null;$filter=(string)($_GET['status']??'');$page=max(1,min(100000,(int)($_GET['page']??1)));
try {
 start();$u=user();$b=business();if(!$b)go('business');$notice=(string)($_SESSION['enquiry_notice']??'');unset($_SESSION['enquiry_notice']);
 if($_SERVER['REQUEST_METHOD']==='POST'){
  csrf();$id=(string)($_POST['id']??'');$status=(string)($_POST['status']??'');if(!preg_match('/\A[0-9a-f-]{36}\z/',$id)||!in_array($status,['New','Contacted','Closed'],true))throw new RuntimeException('Choose a valid enquiry and status.');
  profile_rpc('business_enquiry_status',['p_business'=>$b['id'],'p_environment'=>profile_env(),'p_id'=>$id,'p_status'=>$status,'p_version'=>(int)($_POST['version']??0)]);
  $_SESSION['enquiry_notice']='Status saved.';header('Location: enquiries.php?id='.rawurlencode($id),true,303);exit;
 }
} catch(AccountSessionExpired $e){$_SESSION=['csrf'=>bin2hex(random_bytes(32)),'notice'=>$e->getMessage()];session_regenerate_id(true);go('signin');}
catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Enquiries are unavailable. Please try again.';}
try{if($b){
 $prefix='/rest/v1/business_enquiries?business_id=eq.'.rawurlencode($b['id']).'&environment=eq.'.profile_env();
 $id=(string)($_GET['id']??$_POST['id']??'');
 if($id!==''){if(!preg_match('/\A[0-9a-f-]{36}\z/',$id))throw new RuntimeException('Enquiry unavailable.');$r=api($prefix.'&id=eq.'.rawurlencode($id).'&select=id,customer_name,email,phone,requirements,service_name,status,version,created_at,updated_at,customer_id',[],'GET',$_SESSION['auth']['access_token']);$detail=$r[0]??null;if(!$detail)throw new RuntimeException('Enquiry unavailable.');}
 else {if($filter!==''&&!in_array($filter,['New','Contacted','Closed'],true))throw new RuntimeException('Choose a valid status.');$rows=api($prefix.($filter!==''?'&status=eq.'.rawurlencode($filter):'').'&select=id,customer_name,service_name,status,created_at&order=created_at.desc,id.desc&limit=21&offset='.(($page-1)*20),[],'GET',$_SESSION['auth']['access_token']);}
}}
catch(Throwable $e){$error=$e instanceof RuntimeException?$e->getMessage():'Enquiries are unavailable. Please try again.';}
function enquiry_date(string $s,array $b): string {return (new DateTimeImmutable($s))->setTimezone(new DateTimeZone($b['time_zone']?:'UTC'))->format('j M Y, H:i');}
