<?php if($b):?><div class="editor-heading"><div><p class="eyebrow"><?=esc($b['name'])?></p><h1>Enquiries</h1><p class="muted">Customer requests, private to your business.</p></div><a href="index.php?page=welcome">Welcome</a></div>
