<?php elseif(!$error):?><form method="get" class="enquiry-filter"><label for="status">Status</label><select id="status" name="status"><option value="">All enquiries</option><?php foreach(['New','Contacted','Closed'] as $s):?><option <?=$filter===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="button secondary">Filter</button></form><section class="panel"><?php if(!$rows):?><h2>No enquiries<?=$filter!==''?' with this status':' yet'?></h2><p class="muted">Customers can send requests from your published business page.</p><a href="profile.php">Manage business page</a><?php else:foreach(array_slice($rows,0,20) as $r):?><article class="service-card"><div class="service-title"><h2><a href="enquiries.php?id=<?=esc($r['id'])?>"><?=esc($r['customer_name'])?></a></h2><span class="badge"><?=esc($r['status'])?></span></div><p><?=esc($r['service_name']?:'General enquiry')?></p><p class="muted"><?=esc(enquiry_date($r['created_at'],$b))?></p></article><?php endforeach;endif;?></section><nav class="enquiry-pagination" aria-label="Enquiry pages"><?php if($page>1):?><a href="?page=<?=$page-1?>&amp;status=<?=esc($filter)?>">Previous</a><?php endif;?><?php if(count($rows)>20):?><a href="?page=<?=$page+1?>&amp;status=<?=esc($filter)?>">Next</a><?php endif;?></nav><?php endif;endif;?></main><footer>© <?=date('Y')?> FaraiOS</footer></body></html>
